html:
{%- set wo = frappe.db.get_value("Stock Entry", doc.reference_name, "work_order") if doc.reference_doctype == "Stock Entry" and doc.reference_name else None -%}
{%- set status = (doc.fo_qc_status or "Hold") -%}
<style>
	.print-format { margin-top: 3mm; margin-bottom: 3mm; margin-left: 3mm; margin-right: 3mm; padding: 0 !important; width: 94mm !important; max-width: 94mm !important; min-height: 0 !important; }
	.fo-label { font-family: Arial, Helvetica, sans-serif; color: #000; width: 94mm; }
	.fo-label table { width: 100%; border-collapse: collapse; }
	.fo-label td { padding: 0.6mm 1mm; font-size: 8.5pt; vertical-align: top; }
	.fo-label .k { color: #333; width: 15mm; white-space: nowrap; }
	.fo-label .v { white-space: nowrap; font-weight: bold; }
	.fo-label .item { font-size: 11pt; font-weight: bold; line-height: 1.15; }
	.fo-label .batch { font-size: 14pt; font-weight: bold; letter-spacing: 0.5px; border: 0.4mm solid #000; padding: 0.8mm 2mm; margin: 1mm 0; text-align: center; }
	.fo-label .status { font-size: 12pt; font-weight: bold; text-align: center; padding: 1mm; border: 0.6mm solid #000; }
	.fo-label .status.hold, .fo-label .status.rejected { background: #000; color: #fff; }
</style>
<div class="fo-label">
	<div class="item">{{ doc.item }}</div>
	<div>{{ doc.item_name or "" }}</div>
	<div class="batch">{{ doc.name }}</div>
	<table>
		<tr><td class="k">Mfg date</td><td class="v">{{ frappe.utils.formatdate(doc.manufacturing_date) if doc.manufacturing_date else "-" }}</td>
			<td class="k">Expiry</td><td class="v">{{ frappe.utils.formatdate(doc.expiry_date) if doc.expiry_date else "-" }}</td></tr>
		<tr><td class="k">Quantity</td><td class="v">{{ frappe.utils.flt(doc.batch_qty, 3) }} {{ doc.stock_uom or "" }}</td>
			<td class="k">Made by</td><td class="v">{{ wo or "-" }}</td></tr>
		{%- if doc.fo_supplier_batch_no %}
		<tr><td class="k">Supplier lot</td><td colspan="3">{{ doc.fo_supplier_batch_no }}</td></tr>
		{%- endif %}
	</table>
	<div class="status {{ status | lower | replace(' ', '-') }}">QC: {{ status | upper }}</div>
</div>
